        cfg.trainer.enable_progress_bar = False
        cfg.callbacks.progress_bar.enabled = False
        data = Data()
        tasks = []

        def build(component, **kwargs):
            if component is cfg.data:
                return data
            if component is cfg.logger:
                return False
